source.patch:
From e6f279ca1db6f6364dd44d46a6d3edf02c98f5b5 Mon Sep 17 00:00:00 2001
From: Albert Astals Cid <aacid@kde.org>
Date: Fri, 14 Jun 2024 10:17:11 +0200
Subject: [PATCH] We have maxUtf8 so pass it along to be safer

---
 poppler/UTF.cc                     | 4 ++--
 poppler/UTF.h                      | 2 +-
 qt5/tests/check_utf_conversion.cpp | 2 +-
 qt6/tests/check_utf_conversion.cpp | 2 +-
 4 files changed, 5 insertions(+), 5 deletions(-)

diff --git a/poppler/UTF.cc b/poppler/UTF.cc
index 78dac2c..2269a37 100644
--- a/poppler/UTF.cc
+++ b/poppler/UTF.cc
@@ -487,12 +487,12 @@ int utf16ToUtf8(const uint16_t *utf16, char *utf8, int maxUtf8, int maxUtf16)
 // Allocate utf8 string and convert utf16 into it.
 char *utf16ToUtf8(const uint16_t *utf16, int *len)
 {
-    int n = utf16CountUtf8Bytes(utf16);
+    const int n = utf16CountUtf8Bytes(utf16);
     if (len) {
         *len = n;
     }
     char *utf8 = (char *)gmalloc(n + 1);
-    utf16ToUtf8(utf16, utf8);
+    utf16ToUtf8(utf16, utf8, n + 1, INT_MAX);
     return utf8;
 }

diff --git a/poppler/UTF.h b/poppler/UTF.h
index a51e2e3..eaa656b 100644
--- a/poppler/UTF.h
+++ b/poppler/UTF.h
@@ -131,7 +131,7 @@ int POPPLER_PRIVATE_EXPORT utf16CountUtf8Bytes(const uint16_t *utf16);
 //  maxUtf16 - maximum number of UTF-16 code units to convert. Conversion stops when
 //            either this count is reached or a null is encountered.
 // Returns number of UTF-8 bytes written (excluding NULL).
-int POPPLER_PRIVATE_EXPORT utf16ToUtf8(const uint16_t *utf16, char *utf8, int maxUtf8 = INT_MAX, int maxUtf16 = INT_MAX);
+int POPPLER_PRIVATE_EXPORT utf16ToUtf8(const uint16_t *utf16, char *utf8, int maxUtf8, int maxUtf16);

 // Allocate utf8 string and convert utf16 into it.
 char POPPLER_PRIVATE_EXPORT *utf16ToUtf8(const uint16_t *utf16, int *len = nullptr);
diff --git a/qt5/tests/check_utf_conversion.cpp b/qt5/tests/check_utf_conversion.cpp
index 93bae4a..e3933e8 100644
--- a/qt5/tests/check_utf_conversion.cpp
+++ b/qt5/tests/check_utf_conversion.cpp
@@ -113,7 +113,7 @@ void TestUTFConversion::testUTF()
     QCOMPARE(len, (int)strlen(str));
     Q_ASSERT(len < (int)sizeof(utf8Buf)); // if this fails, make utf8Buf larger

-    len = utf16ToUtf8(s.utf16(), utf8Buf);
+    len = utf16ToUtf8(s.utf16(), utf8Buf, sizeof(utf8Buf), INT_MAX);
     QVERIFY(compare(utf8Buf, str));
     QCOMPARE(len, (int)strlen(str));

diff --git a/qt6/tests/check_utf_conversion.cpp b/qt6/tests/check_utf_conversion.cpp
index d5fb0e2..943c553 100644
--- a/qt6/tests/check_utf_conversion.cpp
+++ b/qt6/tests/check_utf_conversion.cpp
@@ -111,7 +111,7 @@ void TestUTFConversion::testUTF()
     QCOMPARE(len, (int)strlen(str));
     Q_ASSERT(len < (int)sizeof(utf8Buf)); // if this fails, make utf8Buf larger

-    len = utf16ToUtf8(s.utf16(), utf8Buf);
+    len = utf16ToUtf8(s.utf16(), utf8Buf, sizeof(utf8Buf), INT_MAX);
     QVERIFY(compare(utf8Buf, str));
     QCOMPARE(len, (int)strlen(str));

-- 
